```ts
import { createFreeCamera, attachFreeControl } from "@babylonjs/lite";
import type { FreeCamera, SceneContext } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface Walkthrough {
  readonly camera: FreeCamera;
  jumpTo(eye: Vec, target: Vec): void;
  dispose(): void;
}

export function createWalkthrough(
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  eye: Vec,
  target: Vec,
): Walkthrough {
  const camera = createFreeCamera(eye, target);
  scene.camera = camera;
  const detach = attachFreeControl(camera, canvas, scene);

  return {
    camera,
    jumpTo(eye: Vec, target: Vec): void {
      const dx = target.x - eye.x;
      const dy = target.y - eye.y;
      const dz = target.z - eye.z;

      camera.position.x = eye.x;
      camera.position.y = eye.y;
      camera.position.z = eye.z;
      camera.target.x = target.x;
      camera.target.y = target.y;
      camera.target.z = target.z;

      const horiz = Math.sqrt(dx * dx + dz * dz);
      camera._yaw = Math.atan2(dx, dz);
      camera._pitch = Math.atan2(dy, horiz);
    },
    dispose(): void {
      detach();
    },
  };
}
```

I created `src/walkthrough.ts` which builds a `FreeCamera` at the given eye/target, sets it as `scene.camera`, attaches the library's free-control (keyboard + mouse) to the canvas, and exposes `jumpTo` (which rewrites position, target, `_yaw`, and `_pitch` so the controls resume coherently from the new view) and `dispose` (which calls the detach function returned by `attachFreeControl`, removing all canvas listeners and the per-frame hook). The one thing I was not sure of is whether `scene.camera` is a plain assignable property on `SceneContext` — the type declarations for `SceneContext` weren't included in what you gave me, so I assumed it is based on your description.
